'use client'

import { useState } from 'react'
import { Copy } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'

interface HashData {
  request_time: string
  merchant_auth_json: string
  merchant_auth_encrypted: string
  hash: string
}

interface ApiResponse {
  response: any
}

export default function Home() {
  const [createForm, setCreateForm] = useState({
    title: 'Test Link 001',
    amount: '0.02',
    description: 'Payment link created from curl',
    payment_limit: '0',
    return_url: 'https://6291d7e1cd0c91932b68dab7.mockapi.io/pushback/api/v1/response/pushbacks',
    merchant_ref_no: 'ref00001'
  })

  const [detailId, setDetailId] = useState('T+ErECeC9uCGj90ylqGUvw==')
  const [createHash, setCreateHash] = useState<HashData | null>(null)
  const [detailHash, setDetailHash] = useState<HashData | null>(null)
  const [createResult, setCreateResult] = useState<any>(null)
  const [detailResult, setDetailResult] = useState<any>(null)
  const [loading, setLoading] = useState(false)

  const copyToClipboard = async (value: unknown) => {
    try {
      await navigator.clipboard.writeText(
        typeof value === 'string' ? value : JSON.stringify(value, null, 2)
      )
    } catch {
      // ignore
    }
  }

  const calculateCreateHash = async () => {
    setLoading(true)
    try {
      const response = await fetch('/api/calculate-create-hash', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(createForm)
      })
      const data = await response.json()
      setCreateHash(data)
    } catch (error) {
      console.error('Error calculating hash:', error)
    }
    setLoading(false)
  }

  const createPaymentLink = async () => {
    setLoading(true)
    try {
      const response = await fetch('/api/create-payment-link', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(createForm)
      })
      const data = await response.json()
      setCreateResult(data)
    } catch (error) {
      console.error('Error creating payment link:', error)
    }
    setLoading(false)
  }

  const calculateDetailHash = async () => {
    setLoading(true)
    try {
      const response = await fetch('/api/calculate-detail-hash', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id: detailId })
      })
      const data = await response.json()
      setDetailHash(data)
    } catch (error) {
      console.error('Error calculating hash:', error)
    }
    setLoading(false)
  }

  const getPaymentLinkDetail = async () => {
    setLoading(true)
    try {
      const response = await fetch('/api/detail-payment-link', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id: detailId })
      })
      const data = await response.json()
      setDetailResult(data)
    } catch (error) {
      console.error('Error getting payment link detail:', error)
    }
    setLoading(false)
  }

  return (
    <div className="min-h-screen bg-[radial-gradient(1200px_circle_at_20%_0%,hsl(var(--primary)/0.12),transparent_55%),radial-gradient(1200px_circle_at_80%_10%,hsl(var(--ring)/0.10),transparent_50%)]">
      <div className="mx-auto max-w-6xl px-4 py-10">
        <header className="mb-8 flex flex-col gap-2">
          <div className="flex items-center justify-between gap-4">
            <div>
              <h1 className="text-3xl font-semibold tracking-tight">PayWay Payment Link API Tester</h1>
              <p className="text-sm text-muted-foreground">
                Create payment links, inspect hash inputs, and fetch link details from the PayWay sandbox.
              </p>
            </div>
            <div className="hidden sm:flex items-center gap-2">
              <span className="rounded-full border bg-background/60 px-3 py-1 text-xs text-muted-foreground backdrop-blur">
                Sandbox
              </span>
            </div>
          </div>
        </header>

        <div className="grid gap-6 md:grid-cols-2">
          {/* Create Payment Link */}
          <Card className="shadow-sm">
            <CardHeader>
              <CardTitle>Create Payment Link</CardTitle>
              <CardDescription>Update values, calculate the hash, then submit to the PayWay API.</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="title">Title</Label>
                  <Input
                    id="title"
                    value={createForm.title}
                    onChange={(e) => setCreateForm({...createForm, title: e.target.value})}
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="amount">Amount</Label>
                  <Input
                    id="amount"
                    type="number"
                    step="0.01"
                    value={createForm.amount}
                    onChange={(e) => setCreateForm({...createForm, amount: e.target.value})}
                  />
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="description">Description</Label>
                <Textarea
                  id="description"
                  value={createForm.description}
                  onChange={(e) => setCreateForm({...createForm, description: e.target.value})}
                />
              </div>

              <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="payment_limit">Payment Limit</Label>
                  <Input
                    id="payment_limit"
                    type="number"
                    value={createForm.payment_limit}
                    onChange={(e) => setCreateForm({...createForm, payment_limit: e.target.value})}
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="merchant_ref_no">Merchant Ref No</Label>
                  <Input
                    id="merchant_ref_no"
                    value={createForm.merchant_ref_no}
                    onChange={(e) => setCreateForm({...createForm, merchant_ref_no: e.target.value})}
                  />
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="return_url">Return URL</Label>
                <Input
                  id="return_url"
                  value={createForm.return_url}
                  onChange={(e) => setCreateForm({...createForm, return_url: e.target.value})}
                />
              </div>

              <div className="flex flex-wrap gap-2">
                <Button onClick={calculateCreateHash} disabled={loading} variant="outline">
                  Calculate Hash
                </Button>
                <Button onClick={createPaymentLink} disabled={loading}>
                  Create Payment Link
                </Button>
              </div>

              {createHash && (
                <div className="mt-2 rounded-xl border bg-background/60 p-4 backdrop-blur">
                  <div className="mb-2 flex items-center justify-between gap-2">
                    <h3 className="text-sm font-medium">Hash calculation</h3>
                    <Button
                      type="button"
                      size="sm"
                      variant="ghost"
                      onClick={() => copyToClipboard(createHash)}
                      className="h-8 px-2"
                    >
                      <Copy className="mr-2 h-4 w-4" /> Copy
                    </Button>
                  </div>
                  <pre className="max-h-64 overflow-auto rounded-lg bg-muted p-3 text-xs leading-relaxed">
                    {JSON.stringify(createHash, null, 2)}
                  </pre>
                </div>
              )}

              {createResult && (
                <div className="mt-2 rounded-xl border bg-background/60 p-4 backdrop-blur">
                  <div className="mb-2 flex items-center justify-between gap-2">
                    <h3 className="text-sm font-medium">API response</h3>
                    <Button
                      type="button"
                      size="sm"
                      variant="ghost"
                      onClick={() => copyToClipboard(createResult.response)}
                      className="h-8 px-2"
                    >
                      <Copy className="mr-2 h-4 w-4" /> Copy
                    </Button>
                  </div>
                  <pre className="max-h-64 overflow-auto rounded-lg bg-muted p-3 text-xs leading-relaxed">
                    {JSON.stringify(createResult.response, null, 2)}
                  </pre>
                </div>
              )}
            </CardContent>
          </Card>

          {/* Get Payment Link Details */}
          <Card className="shadow-sm">
            <CardHeader>
              <CardTitle>Get Payment Link Details</CardTitle>
              <CardDescription>Retrieve details for an existing payment link</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="detail-id">Payment Link ID</Label>
                <Input
                  id="detail-id"
                  value={detailId}
                  onChange={(e) => setDetailId(e.target.value)}
                />
              </div>

              <div className="flex flex-wrap gap-2">
                <Button onClick={calculateDetailHash} disabled={loading} variant="outline">
                  Calculate Hash
                </Button>
                <Button onClick={getPaymentLinkDetail} disabled={loading}>
                  Get Details
                </Button>
              </div>

              {detailHash && (
                <div className="mt-2 rounded-xl border bg-background/60 p-4 backdrop-blur">
                  <div className="mb-2 flex items-center justify-between gap-2">
                    <h3 className="text-sm font-medium">Hash calculation</h3>
                    <Button
                      type="button"
                      size="sm"
                      variant="ghost"
                      onClick={() => copyToClipboard(detailHash)}
                      className="h-8 px-2"
                    >
                      <Copy className="mr-2 h-4 w-4" /> Copy
                    </Button>
                  </div>
                  <pre className="max-h-64 overflow-auto rounded-lg bg-muted p-3 text-xs leading-relaxed">
                    {JSON.stringify(detailHash, null, 2)}
                  </pre>
                </div>
              )}

              {detailResult && (
                <div className="mt-2 rounded-xl border bg-background/60 p-4 backdrop-blur">
                  <div className="mb-2 flex items-center justify-between gap-2">
                    <h3 className="text-sm font-medium">API response</h3>
                    <Button
                      type="button"
                      size="sm"
                      variant="ghost"
                      onClick={() => copyToClipboard(detailResult.response)}
                      className="h-8 px-2"
                    >
                      <Copy className="mr-2 h-4 w-4" /> Copy
                    </Button>
                  </div>
                  <pre className="max-h-64 overflow-auto rounded-lg bg-muted p-3 text-xs leading-relaxed">
                    {JSON.stringify(detailResult.response, null, 2)}
                  </pre>
                </div>
              )}
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  )
}